local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[408902]=b({e[24034],408902,1,4,406,false,200089,1,"deco/character/qianhuangmuyue_0",302002,60,false,false,1,false,false,"1",false,"0,60,1.02","0,60,1.02",false,"0,60,1.02","0,60,1.02","-100,60,1.02",1893,1036,388,1169,720,1849,2141,1169,729,1849,1261},h)g[408903]=b({e[24034],408903,999,169,407,false,200089,3,"deco/character/qianhuangmuyue_qp",false,false,1,false,1,false,false,"1",false,"0,0,1.02","0,0,1.02","200,-300,1","0,0,1.02","0,0,1.02","-40,0,1",1917,944,388,1177,441,1860,2144,1177,637,1860,1261},h)g[409001]=b({e[35057],409001,false,173,408,false,200090,false,"deco/character/jiushi",302002,60,1,false,false,false,-130,"1",false,false,false,false,false,"-50,0,1","-80,0,1","0,430,0.94","-100,0,1","-100,0,1",false,false,false,"-120,0,1","-80,0,1",false,false,"-80,0,1","jiushi"},h)g[409002]=b({e[23057],409002,1,4,409,"「旦那ァ、その手に持ってるネクタイはなんだ、俺にくれるモンだったりして？\nまったく……男にネクタイを結ぶってのは、犬にリードをつけんのと一緒だぜ。\nま、俺ァ忠犬になんかなるつもりはねェけどな。なぁ、旦那？」",200090,1,"deco/character/jiushi_0",302002,60,1,false,false,false,false,"1",false,false,"-40,0,1",false,false,"-40,0,1","jiushi_0"},h)g[409003]=b({e[17045],409003,2,83,410,"「旦那って奴は……隠れようったって、こっちは腐っても情報屋だぜ？\nああもこの日差しよりアツい視線をくれちゃ、どこにいるのかバレバレだ。\nま、一日くらいなら遊びに付き合ってやってもいいぜ。\nやるよ、旦那好みのドリンクだ。……ん？ 当然、来るのがわかってたんで用意しといたモンだ、それがどうかしたか？」",200090,2,"deco/character/jiushi_xr",false,false,false,false,false,false,false,"",1,2913,5000,1429,2732,5333,6333,7566,10666,15933,8000,5333,"jiushi_xr"},h)g[409101]=b({e[35057],409101,false,174,411,false,200091,false,"deco/character/xili",302002,60,false,false,false,false,50,"1",false,"0,20,1","0,20,1",false,"0,20,1","0,20,1","0,20,1","0,130,1","-30,40,1","-20,20,1",false,false,"0,40,1","-80,20,1","-20,20,1",false,false,"-40,0,1","xili"},h)g[409102]=b({e[24057],409102,1,4,412,"「あは、あははっ！ もー、やめてってば！ モヒート！\nモヒートもあんたのこと、家族だって認めたみたいだね。どんなに凶暴な猛獣でも、家族には優しいんだ」",200091,1,"deco/character/xili_0",302002,60,false,false,false,false,false,"1",false,"0,100,1","0,100,1",false,"0,100,1","0,100,1","-100,100,1","xili_0"},h)g[409103]=b({e[9057],409103,20,91,413,"「『Soul』のオフに、一緒にジョギングできてよかった。ありがとう。\n長い距離を走って疲れたでしょう。バテる前に水分とって。\nあれ、ボトル持ってきてないの？\nじゃあ……あんたがいいなら、私の、飲んでもいいよ。」",200091,2,"deco/character/xili_yh","xili_yh"},h)g[409201]=b({e[17057],409201,false,175,414,false,200092,false,"deco/character/ju",302002,60,false,false,false,false,false,"1","ju"},h)g[409202]=b({e[17057],409202,1,4,415,"「とある都市伝説をご存知ですか？\n『クラウンのメイクに隠された本当の顔は絶対に見てはいけない。さもないとクラウンの世界に閉じ込められてしまう。そう、永遠に……』\n「ふ、フフフ。そんな顔をしないでください。都市伝説を実際の出来事にしたい人が出て来るのは自然なことでしょう。\nさて……親愛なる雀士様、クラウンの世界へようこそ。……もう、逃げられませんよ？」",200092,1,"deco/character/ju_0",302002,60,false,false,false,false,false,"1","ju_0"},h)g[409203]=b({e[17045],409203,6,109,416,"「ドッカーン！\nくくっ……花火の音は、実に心地良いものですねぇ。\n人々は『また一年無事に過ごせてハッピー』な～んて浮かれておいでのようで。\nどなた様もまぁ嬉しそうに……実にくだらないですよ。\n……あぁ、そう構えないでください。スペシャルゲストであるあなたがこうしてお見えになったことですし、クラウンとしてきっちりおもてなしいたしましょう。\n本物の『お祭り騒ぎ』とやらをお知りになりたいのであれば、ぜひその足で、絵の中へとおいでください。」",200092,2,"deco/character/ju_cj",false,false,1,false,false,false,false,"1",1,4665,5000,2274,4756,5333,6900,7599,7266,12400,8000,2666,"ju_cj"},h)g[409301]=b({e[46057],409301,false,176,417,false,200093,false,"deco/character/laiya",302002,60,false,false,false,false,-160,"1",false,false,false,false,false,false,false,"0,340,0.97","-60,0,1","-20,0,1",false,false,false,"-80,0,1","-40,-20,1",false,false,"-30,-40,1",1890,824,398,1226,746,1808,3018,1226,746,1808,1037,"laiya"},h)g[409302]=b({e[17034],409302,1,4,418,"「そう。君がありったけの知恵を絞った末に考えた言い訳がそれなのね。\n……そこまで考えたところ残念だけど、ダ・メ。\n私を説得したいのなら、もっと頑張ってもらわないとね。」",200093,1,"deco/character/laiya_0",302002,60,false,false,false,false,false,"1",1941,944,390,897,385,2389,2877,897,638,2389,1261,false,false,false,false,false,false,false,false,false,false,false,false,"laiya_0"},h)g[409303]=b({e[12057],409303,12,90,419,"「私の蒐集室へようこそ。本当に好奇心旺盛ね……そういう子、先生は嫌いじゃないわ。気になるものがあったら教えて、じっくり解説してあげる。部屋の主の方が気になる？わがままな子も、教育しがいがあって好きよ。」",200093,2,"deco/character/laiya_LF",false,false,1,"laiya_lf"},h)